-- 016_relink_students_corrected_classes.sql
-- Re-does student_class links using the corrected timetablestudents_1.csv
-- (fixes naming-variant mismatches from the first student-timetable export, e.g. 11wi/... -> 11w/...)

-- Drop all existing student_class links so we start clean from the corrected source
DELETE FROM student_class WHERE student_id IN (SELECT student_id FROM students WHERE upn IS NOT NULL);

-- Re-link students to their real teaching groups

-- Retire the placeholder classes created by the first (typo-affected) import, now that nothing references them.
-- These were auto-created guesses for group codes that turned out to be naming variants/typos.
-- Safe to remove: they have no timetable_slots and, after the relink above, no student_class rows either.
DELETE FROM classes
WHERE class_code IS NOT NULL
  AND class_id NOT IN (SELECT DISTINCT class_id FROM student_class)
  AND class_id NOT IN (SELECT DISTINCT class_id FROM timetable_slots)
  AND class_code IN (
    '10a/Rp1','12a/Rp1','111/Me','112/Me','113/Me','11LI/Me','11i/Ec1',
    '11wi/Ci1','11wi/En1','11wi/En2','11wi/En3','11wi/En4','11wi/Fr1','11wi/Fr2',
    '11wi/Me1','11wi/Me2','11wi/Me3','11wi/Me4','11wi/Ng1','11wi/Oh1','11wi/Sp1','7a/Ma4'
  );
